Con ARC el compilador inserta las llamadas de retención y liberación; el programador no las escribe. Una propiedad `readonly` solo expone el getter, y la variable de instancia `_balance` se modifica dentro de la clase.

```objectivec
#import <Foundation/Foundation.h>

@interface Account : NSObject
@property(nonatomic, readonly) NSInteger balance;
- (void)deposit:(NSInteger)amount;
- (BOOL)withdraw:(NSInteger)amount;
@end

@implementation Account {
    NSInteger _balance;
}
- (NSInteger)balance { return _balance; }
- (void)deposit:(NSInteger)amount { _balance += amount; }
- (BOOL)withdraw:(NSInteger)amount {
    if (amount > _balance) {
        return NO;
    }
    _balance -= amount;
    return YES;
}
@end
```

